// Standard API response format
export interface ApiResponse<T = any> {
  code: number;
  data?: T;
  message?: string;
  // Add possible backend variations
  Code?: number;
  Data?: T;
  Msg?: string;
  error?: string;
}

// 用户信息接口
export interface UserInfo {
  id: number;
  username: string;
  email: string;
  avatar?: string;
  createTime: string;
  updateTime: string;
}

// 交易记录接口
export interface Transaction {
  id: number;
  amount: number;
  type: 'income' | 'expense';
  categoryId: number;
  categoryName: string;
  description?: string;
  date: string;
  createTime: string;
  updateTime: string;
}

// 分类接口
export interface Category {
  id: number;
  name: string;
  iconId?: number;
  icon?: string;
  color?: string;
  incomeExpense: 'income' | 'expense';
  createTime: string;
  updateTime: string;
}

// 统计数据类型
export interface StatisticData {
  total_assets?: number;
  Income?: {
    Amount?: number;
    Count?: number;
  };
  Expense?: {
    Amount?: number;
    Count?: number;
  };
}

// 月度统计数据
export interface MonthlyStatistic {
  List?: Array<{
    Income?: {
      Amount?: number;
      Count?: number;
    };
    Expense?: {
      Amount?: number;
      Count?: number;
    };
    Date?: string;
  }>;
}

// 请求选项接口
export interface RequestOptions {
  url: string;
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE';
  data?: any;
  params?: any;
  header?: Record<string, string>;
  timeout?: number;
  requireAuth?: boolean;
}
